import os,re,subprocess,json
from pathlib import Path
files=[]
for root,dirs,names in os.walk('.'):
 dirs[:]=[d for d in dirs if d"'!='"'.git']
 for name in names:
  p=Path(root)/name
  if p.is_file() and not p.is_symlink():files.append(p)
patterns={
 'aws-access-key-id':r'\\b(?:AKIA|ASIA)[A-Z0-9]{16}\\b',
 'github-token':r'\\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})\\b',
 'huggingface-token':r'\\bhf_[A-Za-z0-9]{20,}\\b',
 'openai-api-key':r'\\bsk-(?:proj-|svcacct-)?[A-Za-z0-9_-]{32,}\\b',
 'google-api-key':r'\\bAIza[A-Za-z0-9_-]{35}\\b',
 'slack-token':r'\\bxox[baprs]-[A-Za-z0-9-]{20,}\\b',
}
replacements={}
contents={p:p.read_bytes() for p in files}
for p,b in contents.items():
 s=b.decode('utf8',errors='replace')
 for kind,pat in patterns.items():
  for m in re.finditer(pat,s):replacements[m[0]]='<your-'+kind+'>'
 # Literal credential assignments, preserving existing empty/examples/environment lookups.
 for m in re.finditer(r'(AWS_SECRET_ACCESS_KEY|AWS_ACCESS_KEY_ID)(?:[\"\\x27]\\])?\\s*=\\s*[\"\\x27]?(["'^'"\\s\"\\x27]+)',s):
  v=m[2]
  if len(v) in (20,40) and re.fullmatch(r'[A-Za-z0-9/+=]+',v):
   replacements[v]='<your-aws-secret-access-key>' if 'SECRET' in m[1] else '<your-aws-access-key-id>'
changes={}
for p,b in contents.items():
 new=b
 for v,placeholder in replacements.items():new=new.replace(v.encode(),placeholder.encode())
 if new"'!=b:
  p.write_bytes(new);changes[str(p)]=sum(b.count(v.encode()) for v in replacements)
for p in files:
 b=p.read_bytes()
 assert not any(v.encode() in b for v in replacements),str(p)
for p in changes:
 if p.endswith('"'.json'):json.loads(Path(p).read_text())
print(json.dumps({'unique_credentials_replaced':len(replacements),'changed_files_and_occurrences':changes,'original_values_remaining':0},indent=2))
# Keep values only in process memory. Verify that every diff consists solely of substitutions.
tracked=subprocess.check_output(['git','ls-files','-z']).decode().split('\\0')
for p in changes:
 if p in tracked:
  orig=subprocess.check_output(['git','show','HEAD:'+p]);expected=orig
  for v,placeholder in replacements.items():expected=expected.replace(v.encode(),placeholder.encode())
  assert Path(p).read_bytes()==expected,p
print('Verified: tracked changes contain only credential substitutions.')
